SELECT q.*, i.id AS inquiry_id
FROM quotation q
LEFT JOIN inquiry i ON i.id = q.inquiry_id


        q.status = #{q.status}



            AND q.product_name LIKE CONCAT('%', #{q.productName}, '%')


            AND q.supplier_sku = #{q.supplierSku}


            AND q.inquiry_id = #{q.inquiryId}


            AND i.client_id = #{q.inquiryClient}


            AND i.sales_id = #{q.inquirySales}


            AND (
                FIND_IN_SET(#{q.inquiryCountry}, REPLACE(REPLACE(i.country_id, ', ', ','), ' ,', ','))
                OR FIND_IN_SET((SELECT c.name_en FROM country c WHERE c.id = #{q.inquiryCountry}), REPLACE(REPLACE(i.country_id, ', ', ','), ' ,', ','))
                OR FIND_IN_SET((SELECT c.special_name FROM country c WHERE c.id = #{q.inquiryCountry}), REPLACE(REPLACE(i.country_id, ', ', ','), ' ,', ','))
                OR FIND_IN_SET((SELECT c.name_zh FROM country c WHERE c.id = #{q.inquiryCountry}), REPLACE(REPLACE(i.country_id, ', ', ','), ' ,', ','))
                OR FIND_IN_SET((SELECT c.code FROM country c WHERE c.id = #{q.inquiryCountry}), REPLACE(REPLACE(i.country_id, ', ', ','), ' ,', ','))
            )


            AND q.prioritymode = #{q.priorityMode}


            AND (
                q.country = #{q.country}
                OR q.country IN (SELECT c.name_en FROM country c WHERE c.id = #{q.country})
                OR q.country IN (SELECT c.special_name FROM country c WHERE c.id = #{q.country})
                OR q.country IN (SELECT c.name_zh FROM country c WHERE c.id = #{q.country})
                OR q.country IN (SELECT c.code FROM country c WHERE c.id = #{q.country})
            )



ORDER BY q.create_time DESC

